{"code": "async (page) => {
  // Title
  const title = await page.locator('h1.ytd-watch-metadata').textContent();

  // Description - get the expanded description text
  let description = '';
  const descExpand = await page.locator('ytd-text-inline-expander[expanded]').first();
  if (await descExpand.count() > 0) {
    // get the content div inside
    const content = await descExpand.locator('#content').first();
    if (await content.count() > 0) {
      description = await content.textContent();
    }
  }

  // Transcript - get all segment texts
  let transcriptLines = [];
  const transcriptPanel = await page.locator('ytd-engagement-panel-section-list-renderer[target-id="engagement-panel-transcript"]').first();
  if (await transcriptPanel.count() > 0) {
    const segments = await transcriptPanel.locator('ytd-transcript-segment-renderer').all();
    for (const seg of segments) {
      const text = await seg.locator('div.segment-text').textContent();
      if (text) transcriptLines.push(text.trim());
    }
  }

  return { 
    title: title.trim(), 
    description: description.trim(),
    transcript: transcriptLines.join(' ')
  };
}"}

