  // Let's find the link with title "Top 5 Silliest Animal Moments! | BBC Earth"
  const videoLink = await page.locator('a:has-text("Top 5 Silliest Animal Moments! | BBC Earth")').first();
  if (await videoLink.count() > 0) {
    await videoLink.click();
  } else {
    // fallback: click first video result
    await page.locator('a[href*="youtube.com"]').first().click();
  }
  // Wait for YouTube page to load
  await page.waitForSelector('h1.ytd-watch-metadata');
  // Wait for description expand button
  await page.waitForSelector('ytd-text-inline-expander');
  // Expand description if not already expanded
  const moreButton = await page.locator('ytd-text-inline-expander #more').first();
  if (await moreButton.count() > 0) {
