  // Try to find transcript container by searching for "Transcript" heading
  const headings = Array.from(document.querySelectorAll('h2, h3, h4, [role="heading"]'));
  const transcriptHeading = headings.find(h => h.textContent.includes('Transcript'));
  if (!transcriptHeading) return null;

  // Find the parent container that holds transcript lines
  let container = transcriptHeading.parentElement;
  while (container && !container.querySelector('button[aria-label*="seconds"]')) {
    container = container.parentElement;
  }

  if (!container) return null;

  // Get all buttons inside this container
  const buttons = container.querySelectorAll('button');
  const lines = [];
