    // Get description text
    const descriptionEl = await page.$('ytd-video-description-renderer');
    let description = '';
    if (descriptionEl) {
        description = await descriptionEl.textContent();
    }

    // Look for transcript button
    const transcriptButton = await page.$('button[aria-label="Show transcript"]');
    let transcript = '';
    if (transcriptButton) {
        await transcriptButton.click();
        await page.waitForSelector('ytd-transcript-renderer', { timeout: 5000 });
