        if (transcriptTab) {
            await transcriptTab.click();
            await page.waitForTimeout(1000);
            const transcriptPanel = await page.$('ytd-transcript-renderer');
            if (transcriptPanel) {
                transcript = await transcriptPanel.textContent();
            }
        }
    }

    return { title, description, transcript };
}"}

