    await page.evaluate(() => window.scrollBy(0, 500));
    await page.waitForTimeout(1000);

    // Get title
    const title = await page.title();
    console.log('Full title:', title);
    const videoTitle = title.replace(' - YouTube', '');
    console.log('Video title:', videoTitle);

    // Try to get description text using various selectors
    const descriptionSelectors = [
        'ytd-video-description-renderer',
        '#description',
        'div#description yt-formatted-string',
        'ytd-video-description-renderer yt-formatted-string'
    ];
    let description = '';
    for (const selector of descriptionSelectors) {
        const el = await page.$(selector);
        if (el) {
            description = await el.textContent();
            console.log('Found description with selector', selector);
            break;
        }
    }

    // Look for "Show more" button in description
    const showMoreButton = await page.$('button[aria-label="Show more"]');
    if (showMoreButton) {
        console.log('Found Show more button');
        await showMoreButton.click();
        await page.waitForTimeout(500);
        // Re-fetch description
        for (const selector of descriptionSelectors) {
            const el = await page.$(selector);
            if (el) {
                description = await el.textContent();
                break;
            }
        }
    }

    return { videoTitle, description };
}"}

