{"code": "async (page) => {
    // Click More actions button
    const moreActionsButton = await page.waitForSelector('button[aria-label="More actions"]', { timeout: 10000 });
    await moreActionsButton.click();
    // Wait for menu to appear
    await page.waitForSelector('ytd-menu-popup-renderer', { timeout: 5000 });
    // Find menu item with text "Show transcript"
    const menuItems = await page.$$('ytd-menu-service-item-renderer');
    let transcriptItem = null;
    for (const item of menuItems) {
        const text = await item.textContent();
        if (text && text.toLowerCase().includes('transcript')) {
            transcriptItem = item;
            break;
        }
    }
    if (transcriptItem) {
        await transcriptItem.click();
        // Wait for transcript panel to appear
        await page.waitForSelector('ytd-transcript-renderer', { timeout: 5000 });
        const transcriptRenderer = await page.$('ytd-transcript-renderer');
        const transcriptText = await transcriptRenderer.textContent();
        return { transcriptText };
    } else {
        return { error: 'Transcript menu item not found' };
    }
}"}

